fn process_monthly_billing(db: &Database) -> Result<(), Error> {
    let mut tx = db.begin_transaction()?;
    // Modifies 1,000,000 rows in a single transactional write block!
    tx.execute("UPDATE users SET balance = balance - 10 WHERE active = true")?;
    tx.commit()?;
    Ok(())
}
```

fix:
Chunk the massive update process into small, manageable batched transactions.
```rust
fn process_monthly_billing_chunked(db: &Database) -> Result<(), Error> {
    loop {
        let mut tx = db.begin_transaction()?;
        // Update 1,000 rows at a time
        let modified = tx.execute("UPDATE users SET balance = balance - 10 WHERE active = true LIMIT 1000")?;
        tx.commit()?;
        if modified == 0 { break; }
    }
    Ok(())
}
```
